/**
 * Who can apply and what to prepare, for every listing that was imported with
 * only a summary. Written from each programme's official rules (Oct 2026);
 * exact scores, ages and document formats change between rounds, so the
 * detail page still points applicants to the official call.
 *
 * slug → { eligibility: [], documents: [] }. Applied in useOpportunities to
 * any listing whose own eligibility/documents were not edited in the dashboard.
 */

/* ------------------------------------------------------------ Shared parts */

const PASSPORT = 'Passport (photo page)'
const CV = 'CV or résumé'
const TRANSCRIPTS = 'Academic transcripts and degree certificates (with certified translations if not in English)'
const ENGLISH = 'English test results (IELTS, TOEFL or equivalent) unless exempt'
const REFS2 = 'Two academic reference letters'
const REFS3 = 'Three reference letters'
const MOTIVATION = 'Motivation letter / statement of purpose'
const PROPOSAL = 'Research proposal'

const masters = (extra = [], docs = []) => ({
  eligibility: [
    "A bachelor's degree (or final-year student) with strong grades",
    ...extra,
    'English (or the language of instruction) at the level the programme requires',
  ],
  documents: [TRANSCRIPTS, CV, MOTIVATION, REFS2, ENGLISH, PASSPORT, ...docs],
})

const phd = (extra = [], docs = []) => ({
  eligibility: [
    "A master's degree, or a very good bachelor's degree (usually 2:1/upper-second or equivalent) where the programme allows direct entry",
    ...extra,
    'English language proficiency at the level the university requires',
  ],
  documents: [TRANSCRIPTS, CV, PROPOSAL, REFS2, ENGLISH, PASSPORT, ...docs],
})

const undergrad = (extra = [], docs = []) => ({
  eligibility: ['Completing (or recently completed) secondary school with excellent grades', ...extra],
  documents: ['Secondary-school transcripts and certificates', 'Admission application to the university', 'Personal essay(s)', 'Teacher or counsellor recommendation', PASSPORT, ...docs],
})

const unSecretariatIntern = (focus) => ({
  eligibility: [
    "Enrolled in a master's or higher degree, in the final year of a bachelor's, or graduated within the past year",
    `Studying ${focus} or a closely related subject`,
    'Fluent in English or French (other UN languages are an asset)',
    'Available full-time for at least two months; you pay your own travel and need health insurance',
  ],
  documents: ['Online profile and application on UN Careers (careers.un.org)', 'Cover note explaining your interest in the post', 'Proof of enrolment or degree certificate', 'Academic transcripts', 'Proof of medical insurance (once selected)'],
})

const agencyIntern = (agency, focus, extra = []) => ({
  eligibility: [
    "Enrolled in a university degree (often master's level) or graduated within the past one to two years",
    `Studies or experience in ${focus}`,
    `Fluent in English; French, Spanish or another ${agency} working language is an asset`,
    'Not a close relative of a staff member',
    ...extra,
  ],
  documents: [`Online application on the ${agency} careers site`, CV, 'Cover letter', 'Proof of enrolment or recent degree', 'Academic transcripts', 'Proof of health insurance (once selected)'],
})

const ngoIntern = (org) => ({
  eligibility: ['Current student or recent graduate', `Strong interest in ${org}'s mission and relevant studies`, 'Right to work or volunteer in the country of the post (or eligible for remote roles)', 'Good written and spoken English (local languages often needed for field posts)'],
  documents: [CV, 'Cover letter for the specific vacancy', 'References (usually two)', 'Proof of enrolment or degree where requested'],
})

const techIntern = (extra = []) => ({
  eligibility: ["Enrolled in a bachelor's, master's or PhD programme (usually returning to study after the internship)", 'Studying computer science, engineering, data science or a related field', 'Coding experience in at least one programming language', ...extra],
  documents: ['Online application with your CV/résumé', 'Unofficial transcript (sometimes requested)', 'Links to projects, GitHub or portfolio (recommended)', 'Technical interviews and online coding assessment'],
})

const researchGrant = (extra = [], docs = []) => ({
  eligibility: ['Researchers holding a PhD (or equivalent experience) at an eligible university or research institution', ...extra],
  documents: ['Project proposal with aims, methods and expected impact', 'Detailed budget and justification', 'CVs of the lead researcher and team', 'Letter of support from your institution', ...docs],
})

const ngoGrant = (extra = [], docs = []) => ({
  eligibility: ['Registered non-profit organisation, NGO or community group', ...extra, 'A clear project with measurable results and a realistic budget'],
  documents: ['Registration certificate of the organisation', 'Project proposal or concept note', 'Budget', 'Latest annual report or financial statements', ...docs],
})

const fellow = (eligibility, documents) => ({ eligibility, documents })

